// Arithmetic before the model, not inside it.
//
// Asking an LLM to add up a column is the most common way these digests end up
// quietly wrong. The totals are computed here and handed over as facts; the model
// is only asked to write the sentences.

const rows = $input.all().map((i) => i.json);

const since = new Date(Date.now() - 7 * 864e5);
const recent = rows.filter((r) => {
  const d = new Date(r['Date'] ?? r.date ?? 0);
  return !isNaN(d) && d >= since;
});

const money = (r) => Number(String(r['Total'] ?? r.total ?? 0).replace(/[^0-9.\-]/g, '')) || 0;
const total = recent.reduce((sum, r) => sum + money(r), 0);

const byVendor = {};
for (const r of recent) {
  const v = r['Vendor'] ?? r.vendor ?? 'Unknown';
  byVendor[v] = (byVendor[v] ?? 0) + money(r);
}
const top = Object.entries(byVendor)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([v, amt]) => `${v}: ${amt.toFixed(2)}`);

const stillOpen = recent.filter(
  (r) => Number(r['Confidence'] ?? r.confidence ?? 1) < 0.85
).length;

return [
  {
    json: {
      count: recent.length,
      total: total.toFixed(2),
      top_vendors: top,
      still_in_review: stillOpen,
      facts: JSON.stringify(
        {
          invoices_this_week: recent.length,
          total_value: total.toFixed(2),
          top_vendors: top,
          still_awaiting_review: stillOpen,
        },
        null,
        2
      ),
    },
  },
];

